function livingIcon(name,cls=''){return '<svg class="living-icon '+cls+'" viewBox="0 0 24 24" aria-hidden="true">'+(livingIcons[name]||livingIcons.orbit)+'</svg>'}
function livingChart(id,cls=''){return '<svg class="living-chart '+cls+'" viewBox="0 0 200 42" preserveAspectRatio="none" role="img" aria-label="Aguardando amostras"><path class="chart-guides" d="M0 10H200M0 26H200M0 41H200"/><path id="'+id+'-area" class="chart-area"/><path id="'+id+'" class="chart-line"/><text class="chart-wait" x="100" y="25" text-anchor="middle">Coletando histórico</text></svg>'}
function livingPath(values,min,max){const clean=values.map(Number).filter(Number.isFinite);if(clean.length<2)return'';const range=Math.max(.001,max-min),points=clean.map((v,i)=>[i*200/(clean.length-1),38-(v-min)/range*34]);return points.reduce((d,p,i)=>i===0?'M'+p.join(','):d+' Q'+points[i-1].join(',')+' '+[(points[i-1][0]+p[0])/2,(points[i-1][1]+p[1])/2].join(',')+(i===points.length-1?' T'+p.join(','):''),'')}
function livingSetChart(id,values,range,label){const line=$('#'+id);if(!line)return;const clean=values.filter(Number.isFinite);const low=range?.[0]??Math.min(...clean),high=range?.[1]??Math.max(...clean);const d=livingPath(clean,low,high);line.setAttribute('d',d);$('#'+id+'-area')?.setAttribute('d',d?d+' L200 42H0Z':'');line.closest('svg').classList.toggle('has-history',clean.length>=2);line.closest('svg').setAttribute('aria-label',label+(clean.length<2?' · aguardando duas amostras':' · '+clean.length+' amostras'));}
function livingNum(value,digits=1){return Number.isFinite(value)?value.toLocaleString('pt-BR',{maximumFractionDigits:digits}):'—'}
const livingRam=[],livingSignal=[];let livingLastTV=null;
const hub=document.createElement('section');hub.id='device-hub';hub.className='device-hub';hub.setAttribute('aria-label','Conexão e memória da Konka');
hub.innerHTML='<div class="hub-heading"><span><i id="hub-dot"></i><b>Sua Konka</b><small id="hub-state">Aguardando conexão</small></span><small id="hub-storage"></small></div><div class="hub-metrics"><button id="hub-network" class="hub-metric"><span class="hub-label">'+livingIcon('wifi')+'Conexão<span id="hub-quality">—</span></span><div class="hub-value"><strong id="hub-rssi">—</strong><small>dBm</small><span class="hub-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></span></div>'+livingChart('hub-signal-line')+'<small class="hub-caption">Sinal Wi-Fi · últimas leituras</small></button><button id="hub-traffic" class="hub-metric"><span class="hub-label">'+livingIcon('traffic')+'Tráfego de rede<small>Mb/s</small></span><div class="hub-rates"><span><i></i>↓ <strong id="hub-download">—</strong></span><span><i></i>↑ <strong id="hub-upload">—</strong></span></div>'+livingChart('hub-down-line','chart-down')+'<svg class="living-chart chart-upload" viewBox="0 0 200 42" preserveAspectRatio="none" aria-hidden="true"><path id="hub-up-line" class="chart-line"/></svg><small class="hub-caption">Download e upload · tráfego da TV</small></button><button id="hub-memory" class="hub-metric"><span class="hub-label">'+livingIcon('memory')+'Memória<small id="hub-capacity">— GiB</small></span><div class="hub-value"><strong id="hub-percent">—</strong><small>em uso</small><span id="hub-free">— livres</span></div>'+livingChart('hub-ram-line')+'<span class="hub-memory-meter"><i id="hub-meter"></i></span><small class="hub-caption">RAM do sistema inteiro</small></button></div>';
