function livingText(id,value){const el=document.getElementById(id);if(el&&el.textContent!==String(value))el.textContent=String(value)}
function paintLivingHub(){
 if(page!=='home'||!PeepRuntime.visible(hub))return;
 // Escreve somente o que mudou; leitura com mais de 45 s deixa de ser apresentada como atual.
 const d=liveTV,available=d?.ram?.availableBytes,total=d?.ram?.totalBytes,valid=!!d&&!tvError&&Number.isFinite(d.at)&&Date.now()/1000-d.at<45;
 const usage=valid&&Number.isFinite(available)&&total?(total-available)/total*100:null,rssi=valid?d?.network?.rssi:null,interval=window.PeepMetrics?.isNative?'atualização local de 2 s':'ADB a cada 5 s';
 livingText('hub-state',valid?(d.network?.transport||'Rede')+' · '+interval:d?'Última leitura '+new Date(d.at*1000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+' · sem atualização':'Sem leitura da TV');$('#hub-dot').classList.toggle('connected',valid);
 livingText('hub-storage',valid&&Number.isFinite(d.storage?.availableBytes)?gib(d.storage.availableBytes)+' GiB livres no armazenamento':'');
 livingText('hub-rssi',Number.isFinite(rssi)?rssi:'—');livingText('hub-quality',!valid?'Sem leitura':d.network?.transport==='Ethernet'?'Cabo':!Number.isFinite(rssi)?'Sem sinal medido':rssi>=-55?'Excelente':rssi>=-67?'Bom':rssi>=-75?'Regular':'Fraco');
 livingText('hub-percent',usage===null?'—':Math.round(usage)+'%');livingText('hub-capacity',total?gib(total)+' GiB':'— GiB');livingText('hub-free',usage!==null?gib(available)+' GiB livres':'Aguardando leitura');$('#hub-meter').style.width=usage===null?'0%':Math.max(0,Math.min(100,usage))+'%';
 const rates=valid?d.network?.traffic:null;livingText('hub-download',livingNum(rates?.downloadMbps,2));livingText('hub-upload',livingNum(rates?.uploadMbps,2));
 const level=!valid||!Number.isFinite(rssi)?0:rssi>=-55?4:rssi>=-67?3:rssi>=-75?2:1;document.querySelectorAll('.hub-bars i').forEach((el,i)=>el.classList.toggle('on',i<level));
 if(valid&&livingLastTV!==d.at){livingLastTV=d.at;if(usage!==null)livingRam.push(usage);if(Number.isFinite(rssi))livingSignal.push(rssi);for(const list of[livingRam,livingSignal])if(list.length>24)list.shift()}
 livingSetChart('hub-signal-line',livingSignal,[-95,-25],'Força do sinal em dBm');livingSetChart('hub-ram-line',livingRam,[0,100],'Uso de RAM em percentual');
 const down=trafficHistory.down,up=trafficHistory.up,max=Math.max(.1,...down,...up);livingSetChart('hub-down-line',down,[0,max],'Download em megabits por segundo');$('#hub-up-line').setAttribute('d',livingPath(up,0,max));
}
