const ambientHero=document.createElement('div');ambientHero.className='ambient-hero';ambientHero.innerHTML='<div><p class="living-kicker">UM MOMENTO PARA VOCÊ</p><h1>Tudo no seu ritmo.</h1><p class="living-lead">Seu clima, seu panorama, suas escolhas.</p></div><button class="ambient-climate" id="living-weather">'+livingIcon('weather','weather-animated')+'<span><b id="living-temperature">—°</b><small id="living-weather-description">Contagem, MG</small></span></button><div class="ambient-time"><time id="living-clock"></time><span id="living-date"></span></div>';
$('#ambient-dashboard').prepend(ambientHero);$('#living-weather').onclick=()=>weatherPanel();$('#ambient-title').textContent='O mundo lá fora';$('.ambient-heading .eyebrow').textContent='SEU PANORAMA';
const marketSeries={usd:[],usdc:[]},marketStamps={};
for(const [id,icon]of[['usd','dollar'],['ibov','market'],['usdc','coin']]){
 const card=$('#market-'+id);card.classList.add('living-market');card.querySelector('.market-symbol').innerHTML=livingIcon(icon);const chart=document.createElement('div');chart.className='market-visual';
 if(id==='ibov'){chart.append($('#ibov-chart'));chart.insertAdjacentHTML('beforeend','<small>Até 5 pregões · fonte Yahoo Finance</small>')}
 else chart.innerHTML=livingChart('market-'+id+'-line')+'<small id="market-'+id+'-history">Histórico a partir desta sessão</small>';
 card.querySelector('.market-source').before(chart);
}
function paintLivingMarkets(){if(!marketData)return;for(const id of['usd','usdc']){const item=marketData.items[id];if(!item?.ok)continue;const stamp=item.sourceAt||item.fetchedAt;if(stamp!==marketStamps[id]){marketStamps[id]=stamp;marketSeries[id].push(item.value);if(marketSeries[id].length>24)marketSeries[id].shift()}livingSetChart('market-'+id+'-line',marketSeries[id],null,id==='usd'?'Histórico de USD/BRL nesta sessão':'Histórico de USDC/USD nesta sessão');$('#market-'+id+'-history').textContent=marketSeries[id].length<2?'Histórico se forma nas próximas consultas':marketSeries[id].length+' consultas nesta sessão'}
 document.querySelectorAll('.living-market').forEach(card=>{const positive=card.querySelector('.market-change')?.classList.contains('positive');const negative=card.querySelector('.market-change')?.classList.contains('negative');card.dataset.direction=positive?'up':negative?'down':'neutral'});
}
const livingOldMarkets=paintMarkets;paintMarkets=function(){livingOldMarkets();paintLivingMarkets()};paintLivingMarkets();
for(const [id,icon]of[['currency-tool','convert'],['ambient-weather','weather'],['focus-tool','focus'],['ambient-system','orbit']]){$('#'+id).querySelector('svg').outerHTML=livingIcon(icon,'tool-icon')}
$('#ambient-system span').textContent='Seu ritmo';$('#ambient-system small').textContent='Temas e descanso de tela';$('#ambient-system').onclick=()=>livingSettings();

const voice=document.createElement('button');voice.id='voice-assistant';voice.className='icon-button assistant-button';voice.innerHTML=livingIcon('mic')+'<span class="voice-colors" aria-hidden="true"><i></i><i></i><i></i><i></i></span>';$('.status').insertBefore(voice,$('#profile'));describeControl(voice,'Abrir assistente de voz do Google','Assistente de voz · fale com a sua TV');
voice.onclick=()=>{if(typeof PeepTV!=='undefined'&&typeof PeepTV.openAssistant==='function'){PeepTV.openAssistant();return}show('<p class="eyebrow">SUA VOZ, NO COMANDO</p><h2>Assistente de voz</h2><div class="assistant-art">'+livingIcon('mic')+'</div><p>Na Konka, este botão chama o assistente instalado pelo Android. No navegador, use o botão de microfone do controle remoto.</p><p class="inline-note">Se estiver usando o APK antigo, atualize-o para habilitar este atalho.</p>')};

// Preferências explícitas: rotação desligada por padrão; descanso após 5 minutos.
if(![0,2,5,10,15,30].includes(Number(prefs.idleMinutes)))prefs.idleMinutes=5;
if(![0,5,15,30,60].includes(Number(prefs.themeMinutes)))prefs.themeMinutes=0;
if(!Array.isArray(prefs.themePool))prefs.themePool=['crystal','adl-night','adl-absolute','cinema'];
let nextLivingTheme=Date.now()+Math.max(1,prefs.themeMinutes)*60000,rotatingLivingTheme=false;
function livingRotateTheme(){const pool=[...new Set(prefs.themePool)].filter(id=>themeCatalog.some(t=>t.id===id));if(pool.length<2)return;const next=pool[(pool.indexOf(prefs.theme)+1+pool.length)%pool.length];rotatingLivingTheme=true;selectTheme(next);rotatingLivingTheme=false;nextLivingTheme=Date.now()+prefs.themeMinutes*60000;}
const livingSelectTheme=selectTheme;selectTheme=function(id){livingSelectTheme(id);if(!rotatingLivingTheme)nextLivingTheme=Date.now()+Math.max(1,prefs.themeMinutes)*60000};
function livingOptions(){return '<div class="living-options"><h3>'+livingIcon('orbit')+'A tela no seu ritmo</h3><label class="option">Alternar temas<select id="living-theme-cycle"><option value="0">Somente manualmente</option><option value="5">A cada 5 minutos</option><option value="15">A cada 15 minutos</option><option value="30">A cada 30 minutos</option><option value="60">A cada hora</option></select></label><fieldset class="theme-pool"><legend>Temas que participam</legend>'+themeCatalog.map(t=>'<label><input type="checkbox" data-living-theme="'+t.id+'" '+(prefs.themePool.includes(t.id)?'checked':'')+'>'+escapeHTML(t.name)+'</label>').join('')+'</fieldset><label class="option">Descanso após inatividade<select id="living-idle-time"><option value="0">Desativado</option><option value="2">2 minutos</option><option value="5">5 minutos</option><option value="10">10 minutos</option><option value="15">15 minutos</option><option value="30">30 minutos</option></select></label><label class="option">Cenário de descanso<select id="living-idle-style"><option value="aurora">Aurora · luz em movimento</option><option value="orbits">Órbitas · geometria e luz</option><option value="quiet">Silêncio · relógio essencial</option></select></label><button id="living-idle-preview" class="panel-button">'+livingIcon('moon')+'Prévia do descanso</button><p class="inline-note">O descanso é um protetor de tela; não desliga a TV. Qualquer botão ou movimento do mouse retorna. O modo econômico e a preferência de movimento reduzido simplificam as animações.</p></div>'}
function bindLivingOptions(){
 $('#living-theme-cycle').value=String(prefs.themeMinutes);$('#living-idle-time').value=String(prefs.idleMinutes);$('#living-idle-style').value=prefs.idleStyle||'aurora';
 $('#living-theme-cycle').onchange=e=>{prefs.themeMinutes=+e.target.value;nextLivingTheme=Date.now()+Math.max(1,prefs.themeMinutes)*60000;save()};
 document.querySelectorAll('[data-living-theme]').forEach(input=>input.onchange=()=>{const selected=[...document.querySelectorAll('[data-living-theme]:checked')].map(el=>el.dataset.livingTheme);if(!selected.length){input.checked=true;notify('Mantenha pelo menos um tema selecionado.');return}prefs.themePool=selected;save()});
 $('#living-idle-time').onchange=e=>{prefs.idleMinutes=+e.target.value;lastLivingInput=Date.now();save()};$('#living-idle-style').onchange=e=>{prefs.idleStyle=e.target.value;save()};$('#living-idle-preview').onclick=()=>{panel.close();enterLivingIdle()};
}
function livingSettings(){show('<p class="eyebrow">DO SEU JEITO</p><h2>Seu ritmo</h2>'+livingOptions());bindLivingOptions()}
const livingAppearance=appearance;appearance=function(){livingAppearance();$('#panel-content').insertAdjacentHTML('beforeend',livingOptions());bindLivingOptions()};
const livingThemePicker=themePicker;themePicker=function(){livingThemePicker();$('#panel-content').insertAdjacentHTML('beforeend',livingOptions());bindLivingOptions()};$('#themes').onclick=()=>themePicker();$('#glass-shortcut').onclick=()=>appearance();

