const idle=document.createElement('section');idle.id='living-idle';idle.hidden=true;idle.tabIndex=-1;idle.setAttribute('role','region');idle.setAttribute('aria-label','Descanso de tela. Pressione qualquer botão para voltar.');
idle.innerHTML='<div class="idle-light light-one"></div><div class="idle-light light-two"></div><div class="idle-light light-three"></div><div class="idle-orbit orbit-one"></div><div class="idle-orbit orbit-two"></div><div class="idle-stars" aria-hidden="true">'+Array.from({length:22},(_,i)=>'<i style="--x:'+((i*37+11)%100)+'%;--y:'+((i*23+7)%100)+'%;--delay:'+(i%7)+'s"></i>').join('')+'</div><div class="idle-content"><span class="idle-brand">PEEP CONNECT</span><time id="idle-clock"></time><p id="idle-date"></p><span id="idle-weather"></span></div><p class="idle-wake">'+livingIcon('moon')+'Um tempo para respirar<span>Pressione qualquer botão para voltar</span></p>';
document.body.append(idle);
let livingIdleActive=false,lastLivingInput=Date.now(),livingIdleFocus=null,livingLastPointer=null;const livingInert=[];
function paintLivingClock(){const now=new Date(),time=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(now),date=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(now);$('#living-clock').textContent=time;$('#living-date').textContent=date;if($('#idle-clock').dataset.minute!==time){$('#idle-clock').dataset.minute=time;$('#idle-clock').textContent=time;}$('#idle-date').textContent=date;if(weather){const temp=Math.round(weather.current.temperature_2m)+'°';$('#living-temperature').textContent=temp;$('#living-weather-description').textContent=weatherDescription(weather.current.weather_code)+' · Contagem';$('#idle-weather').textContent=temp+' · Contagem, MG'}else{$('#living-temperature').textContent='—°';$('#living-weather-description').textContent='Clima indisponível · Contagem';$('#idle-weather').textContent='Contagem, MG'}}
function enterLivingIdle(){if(livingIdleActive||document.hidden||panel.open)return;livingIdleFocus=document.activeElement;livingIdleActive=true;idle.dataset.style=prefs.idleStyle||'aurora';idle.hidden=false;document.body.classList.add('living-idle-active');for(const el of document.querySelectorAll('.shell,#toast')){livingInert.push([el,el.inert]);el.inert=true}paintLivingClock();idle.focus();}
function wakeLivingIdle(){if(!livingIdleActive)return;livingIdleActive=false;idle.hidden=true;document.body.classList.remove('living-idle-active');for(const [el,value]of livingInert)el.inert=value;livingInert.length=0;lastLivingInput=Date.now();nextLivingTheme=Date.now()+Math.max(1,prefs.themeMinutes)*60000;if(livingIdleFocus?.isConnected)livingIdleFocus.focus();}
window.PeepIdle={get active(){return livingIdleActive},wake:wakeLivingIdle,show:enterLivingIdle};
function livingInput(event){if(event.type==='pointermove'){const next=[event.clientX,event.clientY];if(livingLastPointer&&Math.abs(next[0]-livingLastPointer[0])+Math.abs(next[1]-livingLastPointer[1])<4)return;livingLastPointer=next}if(livingIdleActive){event.preventDefault();event.stopImmediatePropagation();wakeLivingIdle();return}lastLivingInput=Date.now()}
for(const type of['keydown','pointerdown','pointermove','wheel','touchstart'])window.addEventListener(type,livingInput,{capture:true,passive:false});
document.addEventListener('visibilitychange',()=>{lastLivingInput=Date.now();if(document.hidden&&livingIdleActive)wakeLivingIdle()});
setInterval(()=>{if(document.hidden)return;paintLivingClock();if(!livingIdleActive&&!panel.open&&prefs.idleMinutes&&Date.now()-lastLivingInput>=prefs.idleMinutes*60000)enterLivingIdle();if(!livingIdleActive&&!panel.open&&prefs.themeMinutes&&Date.now()>=nextLivingTheme)livingRotateTheme()},5000);
const livingNavigate=navigate;navigate=function(next){livingNavigate(next);paintLivingClock();lastLivingInput=Date.now()};document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));
if(new URLSearchParams(location.search).get('demo')==='1'){document.body.classList.add('living-demo');const originalLivingService=showServiceStatus;showServiceStatus=function(){originalLivingService('Prévia de interface · dados demonstrativos','Valores ilustrativos, sem conexão com a sua TV.',true)};showServiceStatus()}
paintLivingClock();save();
